<script setup lang="ts">
import {storySteps} from '../content/demo'
const el=ref<HTMLElement>(),enabled=useMotionPreference();let clear=()=>{}
onMounted(()=>{const {gsap,ScrollTrigger}=useNuxtApp().$scrollEngine;const setup=()=>{clear();if(!el.value||!enabled.value)return;const root=el.value,steps=root.querySelectorAll('.story-step'),image=root.querySelector('.story-picture');const context=gsap.context(()=>{gsap.set(steps,{autoAlpha:0});gsap.set(steps[0]!,{autoAlpha:1});const tl=gsap.timeline({scrollTrigger:{trigger:root,pin:true,start:'top top',end:()=>`+=${innerHeight*2}`,scrub:true,invalidateOnRefresh:true}});for(let i=1;i<steps.length;i++)tl.to(steps[i-1]!,{autoAlpha:0,y:-24,duration:.25},i-0.4).fromTo(steps[i]!,{autoAlpha:0,y:24},{autoAlpha:1,y:0,duration:.4},i-0.1);tl.to(image,{scale:1.12,rotate:2,duration:3},0);root.classList.add('story-active')},el.value);clear=()=>{context.revert();root.classList.remove('story-active');ScrollTrigger.refresh()}};const stop=watch(enabled,setup);setup();onBeforeUnmount(()=>{clear();stop()})})
</script>
<template><section ref="el" class="story-pin" aria-label="Da massa à mesa"><div class="story-grid wrap"><div class="story-picture"><MotionImage name="Pao_2" alt="Pães rústicos polvilhados com farinha" variant="kenburns"/></div><div class="story-words"><div v-for="step in storySteps" :key="step.title" class="story-step"><h2>{{step.title}}</h2><p>{{step.copy}}</p></div></div></div><div class="story-caption">Da massa à mesa, no tempo certo.</div></section></template>
